it('identifies the full path of a missing nested property', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {address: {type: 'object', required: ['location']}}},
